// Writes js/ui/picture-icons.js: the Lucide icons used as pictures by the picture-matching game
// (content/pictures.json). Usage: node tools/build-picture-icons.mjs <path to lucide-static>/icons
// Lucide (https://lucide.dev) is ISC-licensed, with some icons derived from Feather (MIT); the generated file
// carries Lucide's LICENSE in full, as both licences require.
import { readFileSync, writeFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const dir = process.argv[2];
if (!dir) { console.error('usage: node tools/build-picture-icons.mjs <lucide-static/icons>'); process.exit(2); }
const sets = JSON.parse(readFileSync(join(root, 'content/pictures.json'), 'utf8')).sets;
const out = {};
for (const w of sets.flatMap((s) => s.words)) {
  const svg = readFileSync(join(dir, `${w.icon}.svg`), 'utf8');
  out[w.icon] = svg.replace(/^[\s\S]*?<svg[^>]*>/, '').replace(/<\/svg>\s*$/, '').replace(/\s+/g, ' ').trim();
}
const version = JSON.parse(readFileSync(join(dir, '..', 'package.json'), 'utf8')).version;
const license = readFileSync(join(dir, '..', 'LICENSE'), 'utf8').trim().split('\n').map((l) => `// ${l}`.trimEnd()).join('\n');
writeFileSync(join(root, 'js/ui/picture-icons.js'), `// Pictures for the picture-matching game: icons from Lucide (lucide-static ${version}, https://lucide.dev).
// Generated by tools/build-picture-icons.mjs from content/pictures.json; do not edit by hand. Inner SVG markup
// only (24x24 viewBox, stroke icons). Lucide's licence follows.
//
${license}
export const PICTURES = ${JSON.stringify(out, null, 1)};
`);
console.log(`picture-icons: ${Object.keys(out).length} icons`);
